CP="`"$FORTRESS_HOME"/bin/run_classpath`"
# echo $CP
if [ -z "$JAVA_HOME" ] ; then
  JAVACMD=java
else
  JAVACMD="$JAVA_HOME/bin/java"
fi

if [ -z "$JAVA_FLAGS" ] ; then
  JAVA_FLAGS="-Xmx1536m"
fi

JAVA_FLAGS="$JAVA_FLAGS -Dfile.encoding=UTF-8"

